<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/integrations.php';
if($_SERVER['REQUEST_METHOD']!=='POST'||!verifyCsrf($_POST['csrf']??'')){http_response_code(403);exit('Invalid request.');}
$id=(int)($_POST['id']??0);$local=db();$stmt=$local->prepare('SELECT * FROM jobs WHERE id=?');$stmt->execute([$id]);$job=$stmt->fetch();if(!$job){http_response_code(404);exit('Job not found.');}if(!empty($job['external_id'])){header('Location: job_edit.php?id='.$id.'&published=existing');exit;}
$config=integrationConfig('nonceblox_mysql');if(($config['status']??'')!=='configured'){header('Location: job_edit.php?id='.$id.'&publish_error=integration');exit;}$remote=null;
try{$remote=new PDO('mysql:host='.$config['host'].';port='.($config['port']?:3306).';dbname='.$config['database'].';charset=utf8mb4',$config['username'],integrationSecret($config,'password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_TIMEOUT=>8]);$duplicate=$remote->prepare('SELECT id FROM career WHERE LOWER(TRIM(title))=LOWER(TRIM(?)) LIMIT 1');$duplicate->execute([$job['title']]);if($duplicate->fetchColumn())throw new RuntimeException('A NonceBlox job with this title already exists.');$skills=array_values(array_unique(array_merge(json_decode($job['required_skills_json']??'[]',true)?:[],json_decode($job['preferred_skills_json']??'[]',true)?:[])));$formFields=json_encode(['fname','lname','email','phone','country','state','city','qualification','resume','joining','consent']);$remote->beginTransaction();$insert=$remote->prepare('INSERT INTO career(title,`desc`,tags,`date`,location,form_fields) VALUES(?,?,?,NOW(),?,?)');$insert->execute([$job['title'],$job['description'],implode(', ',$skills),$job['location']?:'Remote',$formFields]);$remoteId=(int)$remote->lastInsertId();$slug=trim(preg_replace('/[^A-Za-z0-9]+/','_',$job['title']),'_');$publicUrl='https://nonceblox.com/career-inner.php?'.rawurlencode($slug).'='.rawurlencode(base64_encode((string)$remoteId));$local->beginTransaction();$local->prepare("UPDATE jobs SET external_id=?,public_url=?,status='open' WHERE id=? AND external_id IS NULL")->execute([$remoteId,$publicUrl,$id]);$local->prepare('INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(?,?,?,?,?)')->execute([currentUser()['id'],'job_published_nonceblox','job',(string)$id,json_encode(['external_id'=>$remoteId,'public_url'=>$publicUrl])]);$remote->commit();$local->commit();header('Location: job_edit.php?id='.$id.'&published=1');
}catch(Throwable $e){if($remote&&$remote->inTransaction())$remote->rollBack();if($local->inTransaction())$local->rollBack();$code=substr(hash('sha256',$e->getMessage().'|'.$id.'|'.microtime(true)),0,12);error_log('NonceBlox publish '.$code.': '.$e->getMessage());header('Location: job_edit.php?id='.$id.'&publish_error='.$code);}
